function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(56501);
var T0=Date.now();/*Signature edition*/
var M=10,LIM=4;
var cands=[];for(var i=0;i<M;i++)cands.push({name:"model-"+i,ram:+(1+R()*15).toFixed(1),tps:Math.round(5+R()*120),q:+(0.5+R()*0.5).toFixed(3)});
var feas=cands.filter(function(c){return c.ram<=LIM;});
feas.sort(function(a,b){return (b.q*Math.log(b.tps))-(a.q*Math.log(a.tps));});
var best=feas[0]||null;
console.log(JSON.stringify({id:"JAH-APX56S-000001",ok:true,metrics:{candidates:M,ram_limit_gb:LIM,feasible:feas.length,chosen:best?best.name:null,chosen_tps:best?best.tps:null,chosen_quality:best?best.q:null,chosen_ram_gb:best?best.ram:null},ms:Date.now()-T0}));

